const appState={data:null,route:'home',currentProjectId:null,projectView:'overview',selectedRunId:null,currentFile:null,fileContent:'',files:[],events:[],system:null,terminal:{},sharedContext:null,sharedContextProjectId:null,contextBusy:false,contextStatus:'',contextParticipants:null,contextRounds:null,previousFocus:null,pendingConfirmation:null,agentProgress:{}};
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const date=v=>v?new Date(v).toLocaleString():'Never', shortDate=v=>v?new Date(v).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'';
const count=v=>Math.max(0,Number(v)||0).toLocaleString(),duration=ms=>{const total=Math.max(0,Math.floor((Number(ms)||0)/1000)),minutes=Math.floor(total/60),seconds=total%60;return minutes?`${minutes}m ${String(seconds).padStart(2,'0')}s`:`${seconds}s`};
const automaticProviderIds=['codex','gemini','ollama','openrouter','tokenin'];
