const paths={home:'M3 11.5 12 4l9 7.5M5 10.5V20h14v-9.5M9 20v-6h6v6',projects:'M3 6.5h7l2 2h9V19H3z',providers:'M8 12h8M12 8v8M12 2v3M12 19v3M2 12h3M19 12h3',collaboration:'M21 15a4 4 0 0 1-4 4H8l-5 3v-7a4 4 0 0 1-1-2.6V7a4 4 0 0 1 4-4h11a4 4 0 0 1 4 4zM7 9h10M7 13h6',runs:'M6 3h12a3 3 0 0 1 3 3v12a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3zm4 5 6 4-6 4z',activity:'M3 12h4l2-6 4 12 2-6h6',backups:'M4 7h16v13H4zM7 4h10v3M9 11h6M9 15h6',settings:'M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6zm0-7v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2m0-14-2 2M7 17l-2 2',overview:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',files:'M6 2h8l4 4v16H6zM14 2v5h5M9 12h6M9 16h6',agents:'M5 7h14v12H5zM9 11h.01M15 11h.01M9 15h6M12 3v4',preview:'M2 12s4-6 10-6 10 6 10 6-4 6-10 6S2 12 2 12zm10-2.5a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5z',validation:'m4 12 5 5L20 6',history:'M3 12a9 9 0 1 0 3-7L3 8M3 3v5h5M12 7v5l3 2'};
function icon(n){return `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[n]||paths.overview}"/></svg>`}
function providerName(id){return id==='user'?(appState.data?.settings?.ownerLabel||'You'):(names[id]||id)}
function providerInitial(id){return initials[id]||'?'}
async function call(promise,{silent=false}={}){const r=await promise;if(!r?.ok){const m=r?.error||'The operation failed.';if(!silent)toast(m,'error');throw new Error(m)}return r.data}
function toast(message,type='success'){const n=document.createElement('div');n.className=`toast ${type}`;n.role=type==='error'?'alert':'status';n.innerHTML=`<b aria-hidden="true">${type==='error'?'!':'✓'}</b><span>${esc(message)}</span>`;$('#toast-root').append(n);setTimeout(()=>n.remove(),4500)}
function badge(kind,label){return `<span class="status-badge ${kind}"><i aria-hidden="true"></i>${esc(label)}</span>`}
function runBadge(s){return badge(s==='completed'?'ready':s==='running'?'working':['pending','queued','awaiting-review','completed-with-errors'].includes(s)?'waiting':s==='rejected'?'neutral':'error',({completed:'Completed','completed-with-errors':'Completed with issues',running:'In progress',pending:'Waiting',queued:'Queued','awaiting-review':'Review edits',rejected:'Edits rejected',failed:'Failed',cancelled:'Interrupted'})[s]||s)}
function tokenProgressFor(run,agent){return appState.agentProgress[`${run.id}:${agent.id}`]||agent.progress||null}
function agentTokenProgress(run,agent){const progress=tokenProgressFor(run,agent);if(!progress||agent.status==='queued')return '';const generated=Math.max(0,Number(progress.generatedTokens)||0),limit=Math.max(1,Number(progress.tokenLimit)||1),percent=Math.max(0,Math.min(100,Number.isFinite(Number(progress.percent))?Number(progress.percent):Math.round(generated/limit*100))),rate=Math.max(0,Number(progress.tokensPerSecond)||0),waiting=agent.status==='running'&&progress.liveTokenCounts===false,estimated=Boolean(progress.tokenCountEstimated),label=agent.status==='running'?(progress.status||(generated?'Generating output':'Preparing output')):agent.status==='completed'?'Generation completed':agent.status==='failed'?'Generation failed':'Generation interrupted',countLabel=waiting?'Tokens reported when response completes':`${estimated?'~':''}${count(generated)} / ${count(limit)} tokens`,percentLabel=waiting?'Live token counts unavailable for this request':`${estimated?'Estimated ':''}${Math.round(percent)}% of output allowance`;return `<div class="agent-token-progress" data-agent-progress="${run.id}:${agent.id}" role="status" aria-live="polite"><div class="token-progress-heading"><span data-token-label>${esc(label)}</span><strong data-token-count>${esc(countLabel)}</strong></div><div class="token-progress-track ${waiting?'indeterminate':''}" ${waiting?'aria-label="Waiting for completed provider response"':`role="progressbar" aria-label="${esc(agent.role)} output tokens" aria-valuemin="0" aria-valuemax="${limit}" aria-valuenow="${generated}"`}><i data-token-fill style="transform:scaleX(${waiting?1:percent/100})"></i></div><div class="token-progress-meta"><span data-token-percent>${esc(percentLabel)}</span><span data-token-rate>${rate?`${rate.toFixed(1)} tokens/sec · `:''}${duration(progress.elapsedMs)} elapsed</span></div></div>`}
function updateAgentProgressNode(node,progress){const generated=Math.max(0,Number(progress.generatedTokens)||0),limit=Math.max(1,Number(progress.tokenLimit)||1),percent=Math.max(0,Math.min(100,Number.isFinite(Number(progress.percent))?Number(progress.percent):Math.round(generated/limit*100))),rate=Math.max(0,Number(progress.tokensPerSecond)||0),waiting=!progress.done&&progress.liveTokenCounts===false,estimated=Boolean(progress.tokenCountEstimated);node.querySelector('[data-token-label]').textContent=progress.done?'Generation completed':progress.status||(generated?'Generating output':'Preparing output');node.querySelector('[data-token-count]').textContent=waiting?'Tokens reported when response completes':`${estimated?'~':''}${count(generated)} / ${count(limit)} tokens`;const track=node.querySelector('.token-progress-track');track?.classList.toggle('indeterminate',waiting);if(waiting){track?.removeAttribute('role');track?.removeAttribute('aria-valuemin');track?.removeAttribute('aria-valuemax');track?.removeAttribute('aria-valuenow');track?.setAttribute('aria-label','Waiting for completed provider response')}else{track?.setAttribute('role','progressbar');track?.setAttribute('aria-valuemin','0');track?.setAttribute('aria-valuemax',String(limit));track?.setAttribute('aria-valuenow',String(generated))}node.querySelector('[data-token-fill]').style.transform=`scaleX(${waiting?1:percent/100})`;node.querySelector('[data-token-percent]').textContent=waiting?'Live token counts unavailable for this request':`${estimated?'Estimated ':''}${Math.round(percent)}% of output allowance`;node.querySelector('[data-token-rate]').textContent=`${rate?`${rate.toFixed(1)} tokens/sec · `:''}${duration(progress.elapsedMs)} elapsed`}
function currentProject(){return appState.data?.projects.find(p=>p.id===appState.currentProjectId)||null}
function projectById(id){return appState.data?.projects.find(p=>p.id===id)||null}
function connectedCount(){const p=appState.data?.providers;return p?automaticProviderIds.filter(id=>p[id]?.connected).length:0}
function options(){const p=appState.data?.providers||{};return automaticProviderIds.filter(id=>p[id]?.connected)}
function setPage(title,subtitle,{actions='',crumbs=[],scope='Application'}={}){$('#page-title').textContent=title;$('#page-subtitle').textContent=subtitle;$('#scope-label').textContent=scope;$('#scope-label').classList.toggle('project-scope',scope!=='Application');$('#top-actions').innerHTML=actions;$('#breadcrumb').innerHTML=(crumbs.length?crumbs:[{label:title}]).map((x,i)=>`${i?'<span aria-hidden="true">/</span>':''}${x.route?`<button data-route="${x.route}">${esc(x.label)}</button>`:`<span aria-current="page">${esc(x.label)}</span>`}`).join('')}
function renderNav(){const running=(appState.data?.runs||[]).filter(r=>r.status==='running').length, items=[['home','Home',''],['projects','Projects',appState.data?.projects.length||''],['providers','Providers',connectedCount()||''],['collaboration','Collaboration',''],['runs','Agent Runs',running||''],['activity','Activity',''],['backups','Backups',''],['settings','Settings','']], projectScoped=appState.route==='workspace'||(appState.route==='collaboration'&&appState.sharedContextProjectId);$('#nav').innerHTML=items.map(([r,l,c])=>{const a=projectScoped?r==='projects':appState.route===r;return `<button class="nav-button ${a?'active':''}" data-route="${r}" ${a?'aria-current="page"':''}>${icon(r)}<span class="nav-text">${l}</span>${c?`<span class="nav-count">${c}</span>`:''}</button>`}).join('');$('#footer-health').innerHTML=`<span class="status-dot ${connectedCount()?'good':''}" aria-hidden="true"></span><span>${connectedCount()?`${connectedCount()} of ${automaticProviderIds.length} providers ready`:'No providers connected'}</span>`}
function renderProjectNav(project,active){const n=$('#project-nav');if(!project){n.hidden=true;n.innerHTML='';return}const tabs=[['overview','Overview'],['files','Files'],['agents','Agents'],['shared-room','Shared Room'],['preview','Preview'],['validation','Validation'],['history','History']];n.hidden=false;n.innerHTML=`<div class="project-nav-context"><span class="project-avatar">${esc(project.name[0]||'P')}</span><span><small>Current project</small><strong>${esc(project.name)}</strong></span></div><div class="project-tabs">${tabs.map(([v,l])=>`<button class="project-tab ${active===v?'active':''}" data-project-view="${v}" ${active===v?'aria-current="page"':''}>${icon(v==='shared-room'?'collaboration':v)}<span>${l}</span></button>`).join('')}</div>`}
function empty(title,text,action='',i='overview'){return `<div class="empty-state"><span class="empty-icon">${icon(i)}</span><strong>${esc(title)}</strong><p>${esc(text)}</p>${action?`<div class="empty-actions">${action}</div>`:''}</div>`}
function notice(kind,title,text,action=''){return `<div class="notice ${kind}" role="${kind==='error'?'alert':'status'}"><b aria-hidden="true">${kind==='success'?'✓':kind==='error'?'!':'i'}</b><div><strong>${esc(title)}</strong><p>${esc(text)}</p></div>${action}</div>`}
function render(){renderNav();if(!appState.data?.onboardingComplete)return renderOnboarding();({home:renderHome,projects:renderProjects,providers:renderProviders,collaboration:renderCollaboration,runs:renderRuns,activity:renderActivity,backups:renderBackups,settings:renderSettings,workspace:renderWorkspace}[appState.route]||renderHome)();decorateDestructiveActions()}
function decorateDestructiveActions(){if(appState.route==='runs'){const run=appState.data.runs.find(r=>r.id===appState.selectedRunId)||appState.data.runs[0];if(run&&run.status!=='running'&&run.review?.status!=='pending')$('#top-actions').insertAdjacentHTML('afterbegin',`<button class="button button-danger" data-delete-run="${run.id}">Delete selected run</button>`)}if(appState.route==='settings')$('#content').insertAdjacentHTML('beforeend','<section class="danger-zone"><span class="eyebrow">Danger zone</span><h2>Delete all Noor application data</h2><p>Removes projects from Noor, agent runs, activity, settings, Shared Room transcripts, saved provider credentials, and pending edit recovery snapshots. Project folders and installed provider software remain on this computer.</p><button class="button button-danger" data-reset-app>Delete all application data</button></section>')}
function renderOnboarding(){renderProjectNav();setPage('Set up Noor AI Studio','Confirm local storage, then connect the providers you want.',{crumbs:[{label:'Welcome'}]});const checks=[['Operating system',`${appState.system?.platform||'Checking'} ${appState.system?.arch||''}`,true],['Local storage',appState.system?.userData||'Checking…',!!appState.system?.userData],['Secret encryption',appState.system?.encryptionAvailable?'Available':'Unavailable',!!appState.system?.encryptionAvailable],['Providers',connectedCount()?`${connectedCount()} connected`:'Connect after setup',true]];$('#content').innerHTML=`<div class="onboarding"><span class="eyebrow">Local-first setup</span><h2>A clearer AI development workspace</h2><p>Projects, provider connections, shared conversations, and agent runs stay visibly separated. Existing local data is preserved.</p><div class="setup-checks">${checks.map(([l,v,ok])=>`<div><b>${ok?'✓':'!'}</b><span><strong>${l}</strong><small>${esc(v)}</small></span>${badge(ok?'ready':'error',ok?'Ready':'Attention')}</div>`).join('')}</div><div class="onboarding-actions"><button class="button button-secondary" data-route="providers">Review providers</button><button class="button button-primary" data-action="complete-onboarding">Continue</button></div></div>`}
function renderHome(){renderProjectNav();const projects=appState.data.projects.slice(0,4),runs=appState.data.runs.slice(0,4),active=appState.data.runs.filter(r=>r.status==='running').length,review=appState.data.runs.filter(r=>r.review?.status==='pending').length;setPage('Home','Your application-wide overview and recommended next action.',{actions:'<button class="button button-secondary" data-action="import-project">Import folder</button><button class="button button-primary" data-action="new-project">New project</button>',crumbs:[{label:'Home'}]});let next=review?[`Review ${review} agent run${review===1?'':'s'}`,'Accept the proposed file edits or restore the project snapshot before starting more work.','<button class="button button-primary" data-route="runs">Review edits</button>']:!projects.length?['Create your first project','A project gives files, agents, validation, and Shared Room a clear scope.','<button class="button button-primary" data-action="new-project">Create project</button>']:connectedCount()===0?['Connect an AI provider','Connect Codex, Gemini, Ollama, or Ox Alpha before starting collaborative work.','<button class="button button-primary" data-route="providers">Connect provider</button>']:[`Continue ${projects[0].name}`,'Open its workspace to edit files, start agents, or enter Shared Room.',`<button class="button button-primary" data-open-project="${projects[0].id}">Open project</button>`];$('#content').innerHTML=`<div class="home-intro"><div><span class="eyebrow">Recommended next step</span><h2>${esc(next[0])}</h2><p>${esc(next[1])}</p></div>${next[2]}</div><div class="metrics"><div><span>Projects</span><strong>${appState.data.projects.length}</strong><small>Registered locally</small></div><div><span>Providers ready</span><strong>${connectedCount()}<em>/4</em></strong><small>Available for automatic work</small></div><div><span>Active runs</span><strong>${active}</strong><small>${active?'Agents currently working':'No agents working'}</small></div><div><span>Needs review</span><strong>${review}</strong><small>Agent edit decisions</small></div></div><div class="content-grid"><section><div class="section-heading"><div><h2>Recent projects</h2><p>Project-scoped workspaces.</p></div><button class="button button-quiet" data-route="projects">View all</button></div>${projects.length?`<div class="surface list">${projects.map(projectRow).join('')}</div>`:empty('No projects yet','Create a project or import a folder.','<button class="button button-primary" data-action="new-project">Create project</button>','projects')}</section><section><div class="section-heading"><div><h2>Recent agent runs</h2><p>Execution and provider status.</p></div><button class="button button-quiet" data-route="runs">View all</button></div>${runs.length?`<div class="surface list">${runs.map(runRow).join('')}</div>`:empty('No agent runs','Open a project to start a reviewed run.','','runs')}</section></div>`}
function projectRow(p){return `<article class="list-row"><span class="row-icon">${icon('projects')}</span><div class="list-row-main"><strong>${esc(p.name)}</strong><span>${esc(p.goal||'No project goal yet')}</span><small>${esc(p.path)}</small></div><button class="button button-secondary" data-open-project="${p.id}">Open</button></article>`}
function runRow(r){const p=projectById(r.projectId),working=r.agents?.find(a=>a.status==='running');return `<button class="list-row row-button" data-open-run="${r.id}"><span class="row-icon">${icon('runs')}</span><span class="list-row-main"><strong>${esc(r.goal)}</strong><span>${esc(p?.name||'Project no longer registered')} · ${esc((r.providers||[r.provider]).filter(Boolean).map(providerName).join(' + '))}</span><small>${working?`${working.role} is working`:date(r.startedAt)}</small></span>${runBadge(r.status)}</button>`}
function renderProjects(){renderProjectNav();setPage('Projects','Each project has its own files, agents, Shared Room, validation, and history.',{actions:'<button class="button button-secondary" data-action="import-project">Import folder</button><button class="button button-primary" data-action="new-project">New project</button>',crumbs:[{label:'Projects'}]});$('#content').innerHTML=`<div class="section-intro"><span class="eyebrow">Project scope</span><h2>Choose where you want to work</h2><p>Actions inside a project affect that folder and its saved context. Providers and global activity remain application-wide.</p></div>${appState.data.projects.length?`<div class="project-grid">${appState.data.projects.map(p=>`<article class="project-card"><div class="project-card-top"><span class="project-avatar large">${esc(p.name[0]||'P')}</span><div>${badge('neutral','Local project')}<h2>${esc(p.name)}</h2></div></div><p>${esc(p.goal||'Add a goal when you start an agent run.')}</p><dl class="detail-list"><div><dt>Folder</dt><dd>${esc(p.path)}</dd></div><div><dt>Last activity</dt><dd>${date(p.lastActivity)}</dd></div></dl><div class="card-actions"><button class="button button-quiet" data-open-folder="${p.id}">Open folder</button><button class="button button-secondary" data-backup="${p.id}">Back up</button><button class="button button-secondary" data-open-project="${p.id}">Open workspace</button><button class="button button-danger button-icon" aria-label="Remove ${esc(p.name)}" data-remove-project="${p.id}">×</button></div></article>`).join('')}</div>`:empty('No projects registered','Create a project or import an existing folder.','<button class="button button-secondary" data-action="import-project">Import folder</button><button class="button button-primary" data-action="new-project">Create project</button>','projects')}`}
function stateFor(p,manual=false){if(manual)return['manual','Manual handoff','Available from a project; not part of Shared Room'];if(p?.connected)return['ready','Connected','Available for Shared Room and agent roles'];if(p?.installed)return['waiting','Installed, disconnected','Connect before assigning work'];return['offline','Unavailable','Set up before assigning work']}
function providerCard(id,title,type,desc,p,actions,extra=''){const s=stateFor(p,id==='antigravity'),models=p?.models||[];return `<article class="provider-card"><header><span class="provider-logo ${id}">${providerInitial(id)}</span><div><span class="eyebrow">${type}</span><h2>${title}</h2></div>${badge(s[0],s[1])}</header><p>${desc}</p><div class="availability-line"><b>${s[0]==='ready'?'✓':s[0]==='manual'?'↗':'!'}</b>${s[2]}</div><dl class="detail-list"><div><dt>Status detail</dt><dd>${esc(p?.detail||s[1])}</dd></div><div><dt>Selected model</dt><dd>${esc(p?.model||(id==='codex'&&p?.connected?'Managed by Codex':'None selected'))}</dd></div><div><dt>Last check</dt><dd>${date(p?.lastCheck)}</dd></div></dl>${models.length?`<div class="field"><label for="model-${id}">Default model</label><select class="input" id="model-${id}" data-provider-model="${id}">${models.map(m=>`<option value="${esc(m.id)}" ${m.id===p.model?'selected':''}>${esc(m.name||m.id)}</option>`).join('')}</select><span class="field-help">Used by new Shared Room and agent work.</span></div>`:''}${extra}<div class="card-actions">${actions}</div></article>`}
function renderProviders(){renderProjectNav();const p=appState.data.providers;setPage('Providers','Application-wide connections and default models used by projects.',{actions:'<button class="button button-secondary" data-action="refresh-all">Refresh all providers</button>',crumbs:[{label:'Providers'}]});$('#content').innerHTML=`<div class="provider-summary"><div><span class="eyebrow">Application scope</span><h2>${connectedCount()} of ${automaticProviderIds.length} automatic providers ready</h2><p>Connections here affect every project. Shared Room and agent setup still choose who participates.</p></div>${automaticProviderIds.filter(id=>id!=='openrouter').map(id=>`<span>${badge(p[id]?.connected?'ready':'offline',providerName(id))}<small>${esc(p[id]?.model||'No model selected')}</small></span>`).join('')}</div><div class="provider-grid">${providerCard('codex','OpenAI Codex','Cloud · automatic','Official Codex CLI. Shared Room is read-only; assigned agents can edit project files.',p.codex,`${!p.codex.installed?'<button class="button button-primary" data-action="codex-install">Install Codex</button>':p.codex.connected?'<button class="button button-danger" data-action="codex-logout">Disconnect</button>':'<button class="button button-primary" data-action="codex-login">Sign in with ChatGPT</button><button class="button button-secondary" data-action="codex-api-key">Use API key</button>'}<button class="button button-quiet" data-action="codex-docs">Official docs</button>`)}${providerCard('gemini','Gemini','Cloud · automatic','Encrypted Google AI Studio key with dynamically discovered compatible models.',p.gemini,`${p.gemini.connected?'<button class="button button-danger" data-action="gemini-disconnect">Disconnect</button>':'<button class="button button-primary" data-action="gemini-connect">Connect Gemini</button>'}<button class="button button-quiet" data-action="gemini-key-page">Open key page</button>`)}${providerCard('ollama','Ollama','Local · automatic','Models run on this computer through the localhost-only Ollama service.',p.ollama,`${!p.ollama.installed?'<button class="button button-primary" data-action="ollama-install">Install and start</button>':!p.ollama.connected?'<button class="button button-primary" data-action="ollama-start">Start service</button><button class="button button-secondary" data-action="ollama-detect">Check again</button>':'<button class="button button-secondary" data-action="ollama-detect">Check service</button><button class="button button-primary" data-action="ollama-pull">Download model</button>'}<button class="button button-quiet" data-action="ollama-download">Official page</button>`)}${providerCard('antigravity','Antigravity','External · manual','Creates a task packet and opens the selected project folder. Noor does not access its credentials.',{detail:'Available as a manual project action'},'<button class="button button-secondary" data-route="projects">Choose project</button>')}</div>`}
function renderCollaborationHub(){renderProjectNav();setPage('Collaboration','Coordinate connected AI providers through project-scoped Shared Rooms.',{actions:'<button class="button button-primary" data-route="projects">Choose a project</button>',crumbs:[{label:'Collaboration'}]});const projects=appState.data.projects,p=appState.data.providers;$('#content').innerHTML=`<div class="collaboration-intro"><div><span class="eyebrow">Application collaboration hub</span><h2>One shared context, several perspectives</h2><p>Codex, Gemini, Ollama, and Ox Alpha can read the same project conversation and contribute in sequence. Each can see earlier contributions before responding.</p><div class="collaboration-flow"><span>You set project context</span><b>→</b><span>Providers contribute in order</span><b>→</b><span>Transcript stays with project</span></div></div><aside><span class="eyebrow">Available participants</span>${['codex','gemini','ollama'].map(id=>`<div class="participant-summary-row"><span class="provider-logo ${id}">${providerInitial(id)}</span><span><strong>${providerName(id)}</strong><small>${esc(p[id]?.model||'No model selected')}</small></span>${badge(p[id]?.connected?'ready':'offline',p[id]?.connected?'Ready':'Not connected')}</div>`).join('')}<button class="button button-quiet" data-route="providers">Manage providers</button></aside></div><section class="section"><div class="section-heading"><div><h2>Open a project Shared Room</h2><p>The transcript and file snapshot belong to the selected project.</p></div></div>${!projects.length?empty('No project available','Create or import a project first.','<button class="button button-primary" data-action="new-project">Create project</button>','collaboration'):!options().length?notice('warning','Connect a provider first','Shared Room needs at least one connected provider.','<button class="button button-secondary" data-route="providers">Open providers</button>'):`<div class="surface list">${projects.map(p=>`<article class="list-row"><span class="project-avatar">${esc(p.name[0]||'P')}</span><div class="list-row-main"><strong>${esc(p.name)}</strong><span>${esc(p.goal||'Project-scoped shared conversation')}</span><small>${esc(p.path)}</small></div><button class="button button-primary" data-open-context="${p.id}">Open Shared Room</button></article>`).join('')}</div>`}</section>`}
async function openSharedRoom(id,newRoom=false){if(!id){appState.route='collaboration';appState.sharedContextProjectId=null;appState.sharedContext=null;return render()}if(appState.sharedContextProjectId!==id){appState.contextParticipants=null;appState.contextRounds=null}appState.currentProjectId=id;appState.sharedContextProjectId=id;if(newRoom)appState.sharedContext=null;appState.route='collaboration';appState.contextStatus='Loading the project transcript…';render();try{appState.sharedContext=await call(newRoom?window.noor.contexts.create(id):window.noor.contexts.getOrCreate(id),{silent:true});appState.contextStatus=''}catch(e){appState.contextStatus=e.message}render()}
function messageCard(m){const id=m.provider||'system',agent=m.role||(id==='user'?'User':'Provider response'),details=[`Agent · ${agent}`,id!=='user'&&id!=='system'?`Provider · ${providerName(id)}`:providerName(id),m.model,m.round?`Round ${m.round}`:null].filter(Boolean).join(' · ');return `<article class="context-message ${id} ${m.kind==='error'?'error':''}" aria-label="${esc(agent)} message from ${esc(providerName(id))}"><span class="context-avatar ${id}">${providerInitial(id)}</span><div class="context-bubble"><header><div><strong>${esc(agent)}</strong><span>${esc(details)}</span></div><time>${shortDate(m.at)}</time></header><div>${esc(m.content).replace(/\n/g,'<br>')}</div></div></article>`}
function renderCollaboration(){if(!appState.sharedContextProjectId)return renderCollaborationHub();const project=projectById(appState.sharedContextProjectId);if(!project){appState.sharedContextProjectId=null;return renderCollaborationHub()}renderProjectNav(project,'shared-room');setPage('Shared Room','Multiple providers read and contribute to one project conversation.',{actions:'<button class="button button-secondary" data-action="new-context">New room</button>',crumbs:[{label:'Projects',route:'projects'},{label:project.name},{label:'Shared Room'}],scope:project.name});const ids=options(),context=appState.sharedContext?.projectId===project.id?appState.sharedContext:null,messages=context?.messages||[],preferred=appState.contextParticipants||appState.data.settings.defaultParticipants||ids,rounds=Number(appState.contextRounds||appState.data.settings.sharedContextRounds||1);$('#content').innerHTML=`${!ids.length?notice('warning','No providers can participate','Connect Codex, Gemini, Ollama, or Ox Alpha.','<button class="button button-secondary" data-route="providers">Manage providers</button>'):''}<div class="room-shell"><aside class="room-sidebar"><div class="room-scope"><span class="eyebrow">Project Shared Room</span><strong>${esc(project.name)}</strong><small>${esc(project.path)}</small></div><div class="room-explainer"><strong>How contributions work</strong><p>Selected providers read this project’s files and saved transcript, then respond in sequence.</p></div><fieldset class="participant-list"><legend>Participating models</legend>${['codex','gemini','ollama'].map(id=>{const p=appState.data.providers[id],ready=!!p?.connected,working=appState.contextBusy&&appState.contextStatus.toLowerCase().includes(providerName(id).toLowerCase().replace('openai ',''));return `<label class="participant ${ready?'':'offline'} ${working?'working':''}"><input type="checkbox" data-context-provider="${id}" ${ready&&preferred.includes(id)?'checked':''} ${ready?'':'disabled'}><span class="provider-logo ${id}">${providerInitial(id)}</span><span><strong>${providerName(id)}</strong><small>${ready?esc(p.model||'Provider default'):'Not connected'}</small></span>${badge(working?'working':ready?'ready':'offline',working?'Working':ready?'Ready':'Offline')}</label>`}).join('')}</fieldset><div class="field"><label for="context-rounds">Conversation rounds</label><select class="input" id="context-rounds"><option value="1" ${rounds===1?'selected':''}>1 round · one response each</option><option value="2" ${rounds===2?'selected':''}>2 rounds · rebut and refine</option></select></div><button class="button button-danger button-block" data-action="clear-context" ${context?.messageCount?'':'disabled'}>Clear room transcript</button></aside><section class="room-main"><header class="room-header"><div><span class="eyebrow">Shared local memory</span><h2>${esc(context?.title||'Preparing room…')}</h2><p>${context?`${context.messageCount} messages · saved locally for ${esc(project.name)}`:'Loading transcript…'}</p></div><div class="provider-stack">${ids.map(id=>`<span class="provider-logo ${id}" aria-label="${providerName(id)}">${providerInitial(id)}</span>`).join('')}</div></header><div class="context-feed" id="context-feed">${messages.length?messages.map(messageCard).join(''):`<div class="room-empty"><span class="empty-icon">${icon('collaboration')}</span><h3>Start this project conversation</h3><p>Ask for an architecture decision, debugging diagnosis, code review, or plan.</p><button class="suggestion" data-context-prompt="Review this project and identify the highest-impact next step.">Identify the next step</button></div>`}</div><div class="context-status ${appState.contextBusy?'working':''}" role="status">${appState.contextBusy?'<span class="spinner"></span>':'<i></i>'}${esc(appState.contextStatus||'Ready for your message')}</div><div class="context-composer"><label class="sr-only" for="context-message">Message for providers</label><textarea class="input" id="context-message" aria-describedby="context-help context-message-error" placeholder="Ask the providers to discuss, compare, review, or solve…" ${appState.contextBusy?'disabled':''}></textarea><p class="form-error" id="context-message-error" hidden></p><div class="composer-footer"><span id="context-help">Ctrl + Enter to send · providers contribute in order</span><button class="button button-primary" data-action="send-context" ${appState.contextBusy||!context||!ids.length?'disabled':''}>${appState.contextBusy?'Providers working…':'Send to providers'}</button></div></div></section></div>`;requestAnimationFrame(()=>{const f=$('#context-feed');if(f)f.scrollTop=f.scrollHeight})}
function renderRuns(){renderProjectNav();const runs=appState.data.runs,selected=runs.find(r=>r.id===appState.selectedRunId)||runs[0];if(selected)appState.selectedRunId=selected.id;setPage('Agent Runs','Application-wide execution status for single and multi-provider work.',{actions:'<button class="button button-primary" data-route="projects">Start from a project</button>',crumbs:[{label:'Agent Runs'}]});$('#content').innerHTML=!runs.length?empty('No agent runs yet','Open a project and start a reviewed plan.','<button class="button button-primary" data-route="projects">Choose project</button>','runs'):`<div class="runs-layout"><aside class="runs-list">${runs.map(r=>`<button class="run-list-item ${r.id===selected.id?'active':''}" data-open-run="${r.id}"><span><strong>${esc(r.goal)}</strong>${runBadge(r.status)}</span><small>${esc(projectById(r.projectId)?.name||'Project no longer registered')}</small><time>${date(r.startedAt)}</time></button>`).join('')}</aside>${runDetails(selected)}</div>`}
function friendlyProviderError(message){let text=String(message||'');text=text.replace(/OpenRouter request failed \(429\): Provider returned error/i,'Ox Alpha was rate-limited by OpenRouter or its upstream provider (429). Your API key is valid; wait for free-model quota or capacity to reset, then use Run again.');text=text.replace(/DevOps returned invalid file output twice \(response is not a JSON object\)\. No output from this agent was applied\.?/i,'Gemini returned non-JSON file output. Noor now uses Gemini’s current structured-output format and ignores thought parts; use Run DevOps again.');text=text.replace(/\bfetch failed\b/i,'The provider network connection failed. New attempts retry temporary connection failures automatically; use Run again.');return text}
function runDetails(run,compact=false){
  if(!run)return '';
  const agents=run.agents||[],done=agents.filter(a=>a.status==='completed').length,active=agents.filter(a=>a.status==='running'),p=projectById(run.projectId),review=run.review,changes=review?.changes||[];
  const activity=active.length?active.map(a=>`${a.role} · ${providerName(a.provider)}`).join(', '):run.status==='awaiting-review'?'Waiting for your edit decision':['completed','completed-with-errors','rejected'].includes(run.status)?'Run finished':'No agent working';
  const reviewPanel=review?.status==='pending'?`<section class="edit-review" aria-labelledby="edit-review-title"><header><div><span class="eyebrow">Approval required</span><h3 id="edit-review-title">Review agent edits</h3><p>${changes.length?`${changes.length} file change${changes.length===1?' is':'s are'} waiting for your decision.`:'No file changes were detected. Confirm the run to close this review.'}</p></div>${badge('waiting','Project paused')}</header>${changes.length?`<ul class="edit-change-list">${changes.map(change=>`<li><span class="change-type ${change.type}">${esc(change.type)}</span><div><strong>${esc(change.path)}</strong><small>${change.agents?.length?change.agents.map(agent=>`${esc(agent.role)} · ${esc(providerName(agent.provider))}`).join(' + '):'Workspace agent · attribution unavailable'}</small></div></li>`).join('')}</ul>`:''}<p class="review-warning">Reject Edits restores the project to its exact pre-run snapshot and removes files created by this run.</p><div class="review-actions"><button class="button button-danger" data-review-run="${run.id}" data-review-decision="reject">Reject Edits</button><button class="button button-primary" data-review-run="${run.id}" data-review-decision="accept">Accept Edits</button></div></section>`:review?.status==='accepted'?notice('success','Edits accepted','The project changes were kept.'):review?.status==='rejected'?notice('warning','Edits rejected','The pre-run project snapshot was restored.'):review?.status==='unavailable'?notice('error','Edit recovery unavailable','The app closed during this run and its recovery snapshot is missing. Review the project manually before continuing.'):'';
  return `<section class="run-detail ${compact?'compact':''}"><header><div><span class="eyebrow">${run.plan?.retryOf?'Agent retry':run.executionMode==='parallel'?'Parallel': 'Sequential'} · ${(run.providers||[run.provider]).filter(Boolean).length>1?'multi-provider collaboration':'single-provider run'}</span><h2>${esc(run.goal)}</h2><p>${esc(p?.name||'Project no longer registered')} · ${date(run.startedAt)}</p></div>${runBadge(run.status)}</header><div class="run-overview"><div><span>Progress</span><strong>${done} of ${agents.length} agents complete</strong><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="${agents.length||1}" aria-valuenow="${done}"><i style="width:${agents.length?done/agents.length*100:0}%"></i></div></div><div><span>Current activity</span><strong>${esc(activity)}</strong></div></div>${reviewPanel}<ol class="agent-sequence">${agents.map((a,i)=>`<li class="${a.status}"><span class="step-number">${a.status==='completed'?'✓':i+1}</span><div><header><strong>${esc(a.role)}</strong>${runBadge(a.status)}</header><span>Agent · ${esc(a.role)} · Provider · ${esc(providerName(a.provider||'system'))}${a.model?` · ${esc(a.model)}`:''}</span><p class="${a.error?'agent-error':''}">${esc(friendlyProviderError(a.error||a.summary||a.purpose||'Waiting to start.'))}</p>${agentTokenProgress(run,a)}${a.files?.length?`<details><summary>${a.files.length} reported file action${a.files.length===1?'':'s'}</summary><p>${esc(a.files.join(', '))}</p></details>`:''}${a.status==='failed'?`<button class="button button-secondary button-small agent-retry-button" data-retry-run="${run.id}" data-retry-agent="${a.id}" ${run.status==='running'||run.review?.status==='pending'?'disabled title="Review or finish the current run before retrying."':''}>Run ${esc(a.role)} again</button>`:''}</div></li>`).join('')}</ol>${run.finalSummary?`<details class="completion-report"><summary>Completion report</summary><pre>${esc(run.finalSummary)}</pre></details>`:''}<div class="run-actions">${p?`<button class="button button-secondary" data-open-project="${p.id}">Open project</button>`:''}${run.status==='running'?`<button class="button button-danger" data-cancel-run="${run.id}">Stop run</button>`:''}</div></section>`}
function eventRow(e){return `<article class="event"><i class="${e.level||'info'}"></i><div><strong>${esc(friendlyProviderError(e.message))}</strong><span>${esc(e.role||'Application event')}</span></div><time>${date(e.at)}</time></article>`}
function renderActivity(){renderProjectNav();setPage('Activity','Application-wide local history for providers, files, collaboration, and runs.',{actions:'<button class="button button-secondary" data-action="reload-events">Reload activity</button>',crumbs:[{label:'Activity'}]});$('#content').innerHTML=`<div class="section-intro"><span class="eyebrow">Local event journal</span><h2>What changed across Noor AI Studio</h2><p>Sensitive credentials are excluded. Project-attributed events also appear in project History.</p></div>${appState.events.length?`<div class="surface timeline">${appState.events.map(eventRow).join('')}</div>`:empty('No activity recorded','Provider checks, file saves, runs, and backups appear here.','','activity')}`}
function renderBackups(){renderProjectNav();setPage('Backups','Create and restore portable project archives.',{actions:'<button class="button button-primary" data-action="restore-backup">Restore backup</button>',crumbs:[{label:'Backups'}]});$('#content').innerHTML=`<div class="section-intro"><span class="eyebrow">Recovery</span><h2>Project files, without generated clutter</h2><p>Archives exclude .git, dependencies, build output, and Noor internal state.</p></div>${appState.data.projects.length?`<div class="surface list">${appState.data.projects.map(p=>`<article class="list-row"><span class="project-avatar">${esc(p.name[0]||'P')}</span><div class="list-row-main"><strong>${esc(p.name)}</strong><span>${esc(p.path)}</span><small>Last activity ${date(p.lastActivity)}</small></div><button class="button button-secondary" data-backup="${p.id}">Create backup</button></article>`).join('')}</div>`:empty('No project to back up','Register a project first.','<button class="button button-primary" data-route="projects">Open projects</button>','backups')}`}
function renderSettings(){renderProjectNav();const s=appState.data.settings;setPage('Settings','Application-wide preferences, storage, and diagnostics.',{actions:'<button class="button button-secondary" data-action="export-diagnostics">Export diagnostics</button><button class="button button-primary" data-action="save-settings">Save settings</button>',crumbs:[{label:'Settings'}]});$('#content').innerHTML=`<div class="settings-layout"><section><div class="section-heading"><div><h2>General preferences</h2><p>Defaults for new project work.</p></div></div><div class="settings-fields"><div class="field"><label for="owner-label">Your display label</label><input class="input" id="owner-label" value="${esc(s.ownerLabel||'Noor')}" aria-describedby="owner-label-error"><span class="field-help">Shown as message ownership in Shared Room.</span><p class="form-error" id="owner-label-error" hidden></p></div><div class="field"><label for="default-provider">Default provider</label><select class="input" id="default-provider"><option value="codex" ${s.defaultProvider==='codex'?'selected':''}>OpenAI Codex</option><option value="gemini" ${s.defaultProvider==='gemini'?'selected':''}>Gemini</option><option value="ollama" ${s.defaultProvider==='ollama'?'selected':''}>Ollama</option><option value="openrouter" ${s.defaultProvider==='openrouter'?'selected':''}>Ox Alpha</option></select></div><div class="field"><label for="max-agents">Maximum planned agents</label><input class="input" id="max-agents" type="number" min="1" max="6" value="${Number(s.maxAgents||4)}" aria-describedby="max-agents-error"><p class="form-error" id="max-agents-error" hidden></p></div><div class="field"><label for="shared-rounds">Default Shared Room rounds</label><select class="input" id="shared-rounds"><option value="1" ${Number(s.sharedContextRounds||1)===1?'selected':''}>1 round · faster</option><option value="2" ${Number(s.sharedContextRounds||1)===2?'selected':''}>2 rounds · rebut and refine</option></select></div></div></section><aside class="system-panel"><span class="eyebrow">This device</span><h2>System and storage</h2><dl class="detail-list"><div><dt>Platform</dt><dd>${esc(appState.system?.platform)} ${esc(appState.system?.arch)}</dd></div><div><dt>Memory</dt><dd>${esc(appState.system?.memoryGb)} GB</dd></div><div><dt>Encrypted secrets</dt><dd>${appState.system?.encryptionAvailable?'Available':'Unavailable'}</dd></div><div><dt>App data</dt><dd>${esc(appState.system?.userData)}</dd></div></dl>${notice(appState.system?.encryptionAvailable?'success':'warning',appState.system?.encryptionAvailable?'Secrets protected':'Encryption unavailable',appState.system?.encryptionAvailable?'Diagnostics exclude credentials.':'Avoid saving credentials until encryption is available.')}</aside></div>`}
async function openWorkspace(id,view='overview'){appState.currentProjectId=id;appState.route='workspace';appState.projectView=view;appState.currentFile=null;appState.fileContent='';try{appState.files=await call(window.noor.projects.listFiles(id))}catch(e){appState.files=[];console.error(e)}render()}
function renderWorkspace(){const p=currentProject();if(!p){appState.route='projects';return renderProjects()}const labels={overview:'Overview',files:'Files',agents:'Agents',preview:'Preview',validation:'Validation',history:'History'},view=labels[appState.projectView]?appState.projectView:'overview',actions={overview:`<button class="button button-secondary" data-open-folder="${p.id}">Open folder</button><button class="button button-primary" data-action="plan-run">New agent run</button>`,files:`<button class="button button-secondary" data-action="reload-files">Refresh files</button>${appState.currentFile?'<button class="button button-primary" data-action="save-file">Save file</button>':''}`,agents:'<button class="button button-primary" data-action="plan-run">New agent run</button>',preview:`<button class="button button-primary" data-preview="${p.id}">Start preview</button>`,validation:'<button class="button button-primary" data-action="run-safe-command">Run selected check</button>',history:''};renderProjectNav(p,view);setPage(labels[view],`${labels[view]} for ${p.name}.`,{actions:actions[view],crumbs:[{label:'Projects',route:'projects'},{label:p.name},{label:labels[view]}],scope:p.name});$('#content').innerHTML=({overview:projectOverview,files:projectFiles,agents:projectAgents,preview:projectPreview,validation:projectValidation,history:projectHistory})[view](p)}
function projectOverview(p){const runs=appState.data.runs.filter(r=>r.projectId===p.id),recent=runs[0],files=appState.files.filter(f=>f.type==='file').length;return `<div class="project-overview-hero"><div><span class="eyebrow">Project workspace</span><h2>${esc(p.name)}</h2><p>${esc(p.goal||'No goal set. Start an agent run to define the next outcome.')}</p><small>${esc(p.path)}</small></div><aside><strong>Actions here affect this project</strong><p>Files, agent runs, Shared Room, validation, previews, and handoffs use this folder and context.</p></aside></div><div class="metrics project-metrics"><div><span>Readable files</span><strong>${files}</strong><small>Available in editor</small></div><div><span>Agent runs</span><strong>${runs.length}</strong><small>${recent?`Latest: ${recent.status}`:'None yet'}</small></div><div><span>Shared Room</span><strong>${options().length}</strong><small>Providers available</small></div></div><div class="content-grid"><section><div class="section-heading"><div><h2>Continue working</h2><p>Project context stays visible.</p></div></div><div class="quick-actions">${[['files','Edit project files','Browse and save text files'],['shared-room','Open Shared Room','Providers discuss one context'],['validation','Validate changes','Run an approved command'],['preview','Start preview','Launch the detected preview']].map(([v,t,d])=>`<button data-project-view="${v}">${icon(v==='shared-room'?'collaboration':v)}<span><strong>${t}</strong><small>${d}</small></span></button>`).join('')}</div></section><section><div class="section-heading"><div><h2>Latest agent run</h2><p>Provider and specialist status.</p></div></div>${recent?runDetails(recent,true):empty('No run for this project','Describe an outcome and review provider assignments.','<button class="button button-primary" data-action="plan-run">Plan first run</button>','agents')}<div class="handoff-panel"><div><strong>Antigravity manual handoff</strong><p>Create a task packet and open this folder.</p></div><button class="button button-secondary" data-handoff="${p.id}">Create handoff</button></div></section></div>`}
function projectFiles(){const files=appState.files.filter(f=>f.type==='file');return `<div class="files-layout"><aside class="file-panel"><header><strong>Project files</strong><span>${files.length} readable</span></header><div class="file-tree">${files.length?files.map(f=>`<button class="file-item ${appState.currentFile===f.path?'active':''}" data-file="${esc(f.path)}">${icon('files')}<span>${esc(f.path)}</span></button>`).join(''):empty('No readable files','Start an agent run or add files.','<button class="button button-primary" data-action="plan-run">Start run</button>','files')}</div></aside><section class="editor-panel"><header><div><span class="eyebrow">File editor</span><strong>${esc(appState.currentFile||'Select a file')}</strong></div></header>${appState.currentFile?`<label class="sr-only" for="editor">File contents</label><textarea id="editor" class="editor" spellcheck="false">${esc(appState.fileContent)}</textarea>`:empty('Choose a file','Saving writes directly to this project folder.','','files')}</section></div>`}
function projectAgents(p){const runs=appState.data.runs.filter(r=>r.projectId===p.id),selected=runs.find(r=>r.id===appState.selectedRunId)||runs[0];return !runs.length?empty('No agent runs in this project','Start with a goal, then review roles and providers.','<button class="button button-primary" data-action="plan-run">Plan run</button>','agents'):`<div class="runs-layout"><aside class="runs-list">${runs.map(r=>`<button class="run-list-item ${r.id===selected.id?'active':''}" data-open-project-run="${r.id}"><span><strong>${esc(r.goal)}</strong>${runBadge(r.status)}</span><small>${esc((r.providers||[r.provider]).filter(Boolean).map(providerName).join(' + '))}</small><time>${date(r.startedAt)}</time></button>`).join('')}</aside>${runDetails(selected)}</div>`}
function projectPreview(p){return `<div class="feature-page"><section><span class="feature-icon">${icon('preview')}</span><span class="eyebrow">Project preview</span><h2>Launch the detected development experience</h2><p>Noor checks existing project configuration and starts a supported preview without replacing scripts.</p>${notice('info','Project-scoped action',`Preview uses ${p.path} and does not affect other projects.`)}</section><aside><h3>Before you start</h3><ul><li>Make sure dependencies are available.</li><li>Run a build or test in Validation first.</li><li>Noor reports when no preview command is detected.</li></ul></aside></div>`}
function projectValidation(p){const out=appState.terminal[p.id]||'Validation output will appear here.\n';return `<div class="validation-layout"><section><span class="eyebrow">Approved commands only</span><h2>Validate ${esc(p.name)}</h2><p>Noor does not expose an unrestricted terminal.</p><div class="field"><label for="safe-command">Validation command</label><select class="input" id="safe-command"><option>git status</option><option>git diff</option><option>npm test</option><option>npm run build</option><option>npm run lint</option></select><span class="field-help">Runs only inside this project folder.</span></div></section><section class="terminal-panel"><header><div><strong>Validation output</strong><span>${esc(p.path)}</span></div><button class="button button-quiet" data-action="clear-terminal">Clear</button></header><pre class="terminal" id="terminal-output" tabindex="0">${esc(out)}</pre></section></div>`}
function projectHistory(p){const events=appState.events.filter(e=>e.projectId===p.id);return `<div class="section-heading"><div><h2>${esc(p.name)} history</h2><p>Events explicitly attributed to this project.</p></div><button class="button button-secondary" data-action="reload-events">Reload</button></div>${events.length?`<div class="surface timeline">${events.map(eventRow).join('')}</div>`:empty('No attributed project events','Use global Activity for the complete journal.','<button class="button button-secondary" data-route="activity">Open Activity</button>','history')}`}
function modal(title,subtitle,body,footer='',large=false){appState.previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'modal-large':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" aria-describedby="modal-subtitle"><header class="modal-header"><div><h2 id="modal-title">${esc(title)}</h2><p id="modal-subtitle">${esc(subtitle)}</p></div><button class="button button-quiet button-icon" aria-label="Close dialog" data-action="close-modal">×</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;requestAnimationFrame(()=>($('#modal-root [autofocus]')||$('#modal-root button,input,textarea,select'))?.focus())}
function closeModal(){$('#modal-root').innerHTML='';appState.pendingConfirmation=null;if(appState.previousFocus?.isConnected)appState.previousFocus.focus()}
function confirmModal(title,text,label,pending){appState.pendingConfirmation=pending;modal(title,'Review the effect before continuing.',`<div class="confirm-content"><b>!</b><p>${esc(text)}</p></div>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-danger" data-action="confirm-pending">${label}</button>`)}
function newProjectModal(){modal('Create a local project','Choose its parent folder after this step.',`<div class="field"><label for="new-project-name">Project name</label><input class="input" id="new-project-name" autofocus aria-describedby="new-project-name-error" placeholder="Customer portal"><p class="form-error" id="new-project-name-error" hidden></p></div><div class="field"><label for="new-project-goal">Initial goal <small>Optional</small></label><textarea class="input" id="new-project-goal"></textarea></div>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="create-project">Create project</button>`)}
function keyModal(id){const config={gemini:['Connect Gemini','The key is validated and encrypted.','Gemini'],codex:['Connect OpenAI Codex','The key goes to the official Codex login command.','OpenAI']}[id];modal(config[0],config[1],`<div class="field"><label for="provider-key">${config[2]} API key</label><input class="input" id="provider-key" type="password" autocomplete="off" autofocus aria-describedby="provider-key-error"><span class="field-help">Never written to normal state, logs, projects, or diagnostics.</span><p class="form-error" id="provider-key-error" hidden></p></div>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="submit-${id}-key">Connect</button>`)}
function progressModal(title,text='Starting…'){modal(title,'Keep Noor AI Studio open while this completes.',`<pre id="progress-text" class="progress-box" role="status">${esc(text)}</pre><div class="progress-track indeterminate"><i id="progress-fill"></i></div>`)}
function providerChoices(ids){return ids.flatMap(id=>id==='tokenin'?(appState.data.providers.tokenin?.models||[]).map(model=>({provider:id,model:model.id,label:`TokenIn · ${model.name||model.id}`})):[{provider:id,model:null,label:`${providerName(id)} · ${appState.data.providers[id].model||'default'}`}])}
function providerChoiceValue(choice){return `${choice.provider}|${choice.model||''}`}
function parseProviderChoice(value){const [provider,...modelParts]=String(value||'').split('|'),model=modelParts.join('|');return model?{provider,model}:{provider}}
function providerOptions(ids,selectedIndex=0){const choices=providerChoices(ids);return choices.map((choice,index)=>`<option value="${esc(providerChoiceValue(choice))}" ${index===selectedIndex%choices.length?'selected':''}>${esc(choice.label)}</option>`).join('')}
function ordinal(value){const number=Number(value),remainder=number%100;if(remainder>=11&&remainder<=13)return `${number}th`;return `${number}${({1:'st',2:'nd',3:'rd'})[number%10]||'th'}`}
function orderOptions(total,selected){return Array.from({length:total},(_,index)=>{const position=index+1;return `<option value="${position}" ${position===selected?'selected':''}>${ordinal(position)}</option>`}).join('')}
function refreshRoleOrderControls(){
  const controls=$$('[data-role-order]',$('#modal-root'));
  const ordered=[...controls].sort((left,right)=>(Number(left.dataset.previousOrder||left.value)||Number.MAX_SAFE_INTEGER)-(Number(right.dataset.previousOrder||right.value)||Number.MAX_SAFE_INTEGER)||controls.indexOf(left)-controls.indexOf(right));
  const positions=new Map(ordered.map((control,index)=>[control,index+1]));
  for(const control of controls){const position=positions.get(control);control.innerHTML=orderOptions(controls.length,position);control.value=String(position);control.dataset.previousOrder=String(position)}
}
function planModal(plan){
  const p=currentProject(),ids=options();
  if(!ids.length){toast('Connect at least one provider first.','error');appState.route='providers';return render()}
  const total=plan.roles.length;
  const generatedTasks=plan.roles.map((r,i)=>`<article><div><strong>${esc(r.role)}</strong>${badge('waiting','May edit files')}<p>${esc(r.purpose)}</p></div><div class="role-assignment-controls"><div class="role-order-field"><label for="role-order-${i}">Run order</label><select class="input" id="role-order-${i}" data-role-order data-generated-role-index="${i}" data-previous-order="${i+1}">${orderOptions(total,i+1)}</select></div><div class="role-provider-field"><label for="role-${i}">Assign agent</label><select class="input" id="role-${i}" data-role-provider="${esc(r.role)}">${providerOptions(ids,i)}</select></div></div></article>`).join('');
  const customSection=`<section class="custom-task-section" aria-labelledby="custom-task-heading"><header><div><h3 id="custom-task-heading">Your custom tasks</h3><p>Add work the generated plan missed, choose its agent, and place it anywhere in the run.</p></div><button class="button button-secondary button-small" data-action="add-custom-task">+ Add custom task</button></header><div class="custom-task-list" id="custom-task-list" aria-live="polite"></div><p class="field-help">Use Run order on every role to decide what runs first, second, third, or later. Later sequential agents inherit earlier results.</p></section>`;
  modal('Review agent run',`Project: ${p.name}`,`<div class="shared-plan-banner"><div class="provider-stack">${ids.map(id=>`<span class="provider-logo ${id}">${providerInitial(id)}</span>`).join('')}</div><div><strong>${ids.length>1?'Multi-provider collaboration available':'Single-provider run'}</strong><p>Every assigned agent can create or edit project files. All changes require your approval after the run.</p></div></div><label class="parallel-mode-toggle" for="parallel-mode"><input type="checkbox" id="parallel-mode"><span><strong>Parallel mode</strong><small>Run every agent at the same time. Faster, but agents begin from the same shared context and may touch overlapping files.</small></span>${badge('neutral','Optional')}</label><div class="field"><label for="run-goal">Outcome</label><textarea class="input" id="run-goal" aria-describedby="run-goal-error">${esc(plan.goal)}</textarea><p class="form-error" id="run-goal-error" hidden></p></div><div class="role-assignment-list">${generatedTasks}</div>${customSection}`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-start-run="${plan.id}">Start agent run</button>`,true);
  $('#modal-root').dataset.plan=JSON.stringify(plan);
}
let customTaskSequence=0;
function addCustomTask(){
  const list=$('#custom-task-list'),ids=options();
  if(!list)return;
  if($$('[data-custom-task]',list).length>=6)return toast('A run can include up to 6 custom tasks.','error');
  const sequence=++customTaskSequence,position=$$('[data-role-order]',$('#modal-root')).length+1,article=document.createElement('article');
  article.className='custom-task-card';article.dataset.customTask=String(sequence);
  article.innerHTML=`<div class="custom-task-copy"><label for="custom-task-${sequence}">Task instructions</label><textarea class="input" id="custom-task-${sequence}" data-custom-task-input aria-describedby="custom-task-${sequence}-help custom-task-${sequence}-error" placeholder="For example: audit the authentication flow and fix the highest-risk issue."></textarea><span class="field-help" id="custom-task-${sequence}-help">This agent may edit project files.</span><p class="form-error" id="custom-task-${sequence}-error" hidden></p></div><div class="custom-task-agent"><div class="role-order-field"><label for="custom-task-order-${sequence}">Run order</label><select class="input" id="custom-task-order-${sequence}" data-role-order data-previous-order="${position}">${orderOptions(position,position)}</select></div><div class="role-provider-field"><label for="custom-task-provider-${sequence}">Assign agent</label><select class="input" id="custom-task-provider-${sequence}" data-custom-task-provider>${providerOptions(ids,sequence-1)}</select></div><button class="button button-quiet button-small" data-action="remove-custom-task" aria-label="Remove this custom task">Remove</button></div>`;
  list.append(article);refreshRoleOrderControls();article.querySelector('textarea')?.focus();
}
function errorFor(id,message){const input=$(`#${id}`),e=$(`#${id}-error`);input?.setAttribute('aria-invalid','true');if(e){e.textContent=message;e.hidden=false}input?.focus()}
function clearError(id){const input=$(`#${id}`),e=$(`#${id}-error`);input?.removeAttribute('aria-invalid');if(e)e.hidden=true}
async function refreshState(){appState.data=await call(window.noor.app.getState(),{silent:true});render()}
async function loadInitial(){try{[appState.data,appState.events,appState.system]=await Promise.all([call(window.noor.app.getState(),{silent:true}),call(window.noor.app.getEvents(300),{silent:true}),call(window.noor.app.systemInfo(),{silent:true})]);render()}catch(e){setPage('Unable to open Noor AI Studio','Application state could not be loaded.');$('#content').innerHTML=empty('Failed to load',e.message,'<button class="button button-primary" data-action="retry-load">Try again</button>','activity')}}
async function handleAction(a){if(a==='close-modal')return closeModal();if(a==='retry-load')return loadInitial();if(a==='complete-onboarding'){appState.data=await call(window.noor.app.completeOnboarding());return render()}if(a==='new-project')return newProjectModal();if(a==='create-project'){const name=$('#new-project-name').value.trim();if(!name)return errorFor('new-project-name','Enter a project name.');const p=await call(window.noor.projects.create({name,goal:$('#new-project-goal').value.trim()}));closeModal();await refreshState();return openWorkspace(p.id)}if(a==='import-project'){const p=await call(window.noor.projects.import());await refreshState();return openWorkspace(p.id)}if(a==='refresh-all'){progressModal('Checking providers');try{await call(window.noor.providers.refreshAll());toast('Provider status refreshed.')}finally{closeModal();await refreshState()}return}if(a==='reload-events'){appState.events=await call(window.noor.app.getEvents(500));return render()}if(a==='codex-install'){progressModal('Installing OpenAI Codex','Downloading the official package…');try{await call(window.noor.providers.codexInstall());toast('Codex installed.')}finally{closeModal();await refreshState()}return}if(a==='codex-login'){progressModal('OpenAI Codex sign-in','Complete the official browser sign-in.');try{await call(window.noor.providers.codexLogin(false));toast('Codex connected.')}finally{closeModal();await refreshState()}return}if(a==='codex-api-key')return keyModal('codex');if(a==='gemini-connect')return keyModal('gemini');if(a==='submit-codex-key'||a==='submit-gemini-key'){const key=$('#provider-key').value.trim();if(!key)return errorFor('provider-key','Enter an API key.');const codex=a.includes('codex');progressModal(`Connecting ${codex?'OpenAI Codex':'Gemini'}`,'Validating credentials…');try{await call(codex?window.noor.providers.codexApiKey(key):window.noor.providers.geminiConnect(key));toast(`${codex?'Codex':'Gemini'} connected.`)}finally{closeModal();await refreshState()}return}if(a==='codex-logout'){await call(window.noor.providers.codexLogout());await refreshState();return toast('Codex disconnected.')}if(a==='codex-docs')return call(window.noor.providers.openUrl('codex'));if(a==='gemini-disconnect'){await call(window.noor.providers.geminiDisconnect());await refreshState();return toast('Gemini disconnected.')}if(a==='gemini-key-page')return call(window.noor.providers.openUrl('gemini'));if(a==='ollama-detect'){await call(window.noor.providers.ollamaDetect());await refreshState();return toast('Ollama status checked.')}if(a==='ollama-install'||a==='ollama-start'){progressModal(a==='ollama-install'?'Install and start Ollama':'Start Ollama','Waiting for the local service…');try{await call(a==='ollama-install'?window.noor.providers.ollamaInstall():window.noor.providers.ollamaStart());toast('Ollama is ready.')}finally{closeModal();await refreshState()}return}if(a==='ollama-download')return call(window.noor.providers.openUrl('ollama'));if(a==='ollama-pull'){modal('Download an Ollama model','The local service performs the download.','<div class="field"><label for="ollama-model">Model name</label><input class="input" id="ollama-model" value="gemma3" autofocus aria-describedby="ollama-model-error"><p class="form-error" id="ollama-model-error" hidden></p></div>','<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="submit-ollama-pull">Download</button>');return}if(a==='submit-ollama-pull'){const m=$('#ollama-model').value.trim();if(!m)return errorFor('ollama-model','Enter a model name.');progressModal('Downloading model');try{await call(window.noor.providers.ollamaPull(m));toast('Model downloaded.')}finally{closeModal();await refreshState()}return}if(a==='new-context')return openSharedRoom(appState.sharedContextProjectId,true);if(a==='clear-context')return confirmModal('Clear Shared Room transcript?','Every message in this project room will be removed. Project files are not affected.','Clear transcript',{type:'clear-context',id:appState.sharedContext.id});if(a==='confirm-pending'){const p=appState.pendingConfirmation;if(p?.type==='clear-context'){closeModal();appState.sharedContext=await call(window.noor.contexts.clear(p.id));toast('Transcript cleared.');return renderCollaboration()}if(p?.type==='remove-project'){closeModal();await call(window.noor.projects.remove(p.id));await refreshState();return toast('Project removed. Its folder was not deleted.')}}if(a==='send-context'){const message=$('#context-message')?.value.trim(),participants=$$('[data-context-provider]:checked').map(n=>n.dataset.contextProvider),rounds=Number($('#context-rounds').value);if(!message)return errorFor('context-message','Write a message for the providers.');if(!participants.length)return errorFor('context-message','Select at least one provider.');appState.contextParticipants=participants;appState.contextRounds=rounds;appState.contextBusy=true;appState.contextStatus=`Starting ${participants.map(providerName).join(', ')} · round 1 of ${rounds}`;renderCollaboration();try{appState.sharedContext=await call(window.noor.contexts.send({projectId:appState.sharedContextProjectId,contextId:appState.sharedContext?.id,message,participants,rounds}));appState.contextStatus='All providers contributed.';toast('Shared conversation completed.')}finally{appState.contextBusy=false;renderCollaboration()}return}if(a==='plan-run'){const p=currentProject();modal('Describe the outcome',`Project: ${p.name}`,`<div class="field"><label for="plan-goal">What should agents build or change?</label><textarea class="input" id="plan-goal" autofocus aria-describedby="plan-goal-error">${esc(p.goal||'')}</textarea><p class="form-error" id="plan-goal-error" hidden></p></div>`,'<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="create-plan">Review plan</button>');return}if(a==='create-plan'){const goal=$('#plan-goal').value.trim();if(!goal)return errorFor('plan-goal','Describe the outcome.');return planModal(await call(window.noor.orchestrator.plan(goal)))}if(a==='reload-files'){appState.files=await call(window.noor.projects.listFiles(appState.currentProjectId));return renderWorkspace()}if(a==='save-file'){await call(window.noor.projects.saveFile(appState.currentProjectId,appState.currentFile,$('#editor').value));appState.fileContent=$('#editor').value;return toast('File saved.')}if(a==='run-safe-command'){const c=$('#safe-command')?.value;if(!c)return toast('Choose a command.','error');await call(window.noor.tools.safeCommand(appState.currentProjectId,c));return toast(`${c} started.`)}if(a==='clear-terminal'){appState.terminal[appState.currentProjectId]='';return renderWorkspace()}if(a==='restore-backup'){const r=await call(window.noor.tools.restore());return toast(`Restored ${r.restored.length} files.`)}if(a==='save-settings'){const ownerLabel=$('#owner-label').value.trim(),maxAgents=Number($('#max-agents').value);if(!ownerLabel)return errorFor('owner-label','Enter a display label.');if(!Number.isInteger(maxAgents)||maxAgents<1||maxAgents>6)return errorFor('max-agents','Choose 1 to 6.');appState.data=await call(window.noor.app.updateSettings({ownerLabel,defaultProvider:$('#default-provider').value,maxAgents,sharedContextRounds:Number($('#shared-rounds').value)}));render();return toast('Settings saved.')}if(a==='export-diagnostics'){const f=await call(window.noor.tools.exportDiagnostics());return toast(`Diagnostics saved to ${f}`)}}
document.addEventListener('click',e=>{
  const action=e.target.closest('[data-action]')?.dataset.action;
  if(action==='add-custom-task'){e.preventDefault();e.stopImmediatePropagation();return addCustomTask()}
  if(action==='remove-custom-task'){e.preventDefault();e.stopImmediatePropagation();e.target.closest('[data-custom-task]')?.remove();refreshRoleOrderControls();return $('[data-action="add-custom-task"]')?.focus()}
  if(!e.target.closest('[data-start-run]'))return;
  const modalRoot=$('#modal-root'),rows=$$('[data-custom-task]',modalRoot);
  const plan=JSON.parse(modalRoot.dataset.plan||'{}');
  plan.parallel=Boolean($('#parallel-mode',modalRoot)?.checked);
  const generatedRoles=(plan.roles||[]).filter(role=>!role.custom).map((role,index)=>({...role,executionOrder:Number($(`[data-generated-role-index="${index}"]`,modalRoot)?.value)||index+1}));
  const customRoles=[];
  for(const [index,row] of rows.entries()){
    const input=row.querySelector('[data-custom-task-input]'),purpose=input.value.trim();
    if(!purpose){e.preventDefault();e.stopImmediatePropagation();return errorFor(input.id,'Describe what this custom agent should do.')}
    const role=`Custom task ${index+1}`,provider=row.querySelector('[data-custom-task-provider]');
    provider.dataset.roleProvider=role;
    customRoles.push({role,purpose,writes:true,custom:true,executionOrder:Number($('[data-role-order]',row)?.value)||generatedRoles.length+index+1});
  }
  const roles=[...generatedRoles,...customRoles],orders=roles.map(role=>role.executionOrder);
  if(new Set(orders).size!==roles.length||orders.some(order=>!Number.isInteger(order)||order<1||order>roles.length)){e.preventDefault();e.stopImmediatePropagation();return toast('Choose a different run position for every role.','error')}
  plan.roles=roles.sort((left,right)=>left.executionOrder-right.executionOrder);
  modalRoot.dataset.plan=JSON.stringify(plan);
},true);
async function openProjectView(v){const p=currentProject()||projectById(appState.sharedContextProjectId);if(!p)return;if(v==='shared-room')return openSharedRoom(p.id);appState.currentProjectId=p.id;appState.route='workspace';appState.projectView=v;if(!appState.files.length)try{appState.files=await call(window.noor.projects.listFiles(p.id))}catch(e){console.error(e)}render()}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-file]');if(!el)return;try{if(el.dataset.route){if(!appState.data?.onboardingComplete&&el.dataset.route!=='providers')return;appState.route=el.dataset.route;if(el.dataset.route==='collaboration'){appState.sharedContextProjectId=null;appState.sharedContext=null}return render()}if(el.dataset.projectView)return openProjectView(el.dataset.projectView);if(el.dataset.contextPrompt){$('#context-message').value=el.dataset.contextPrompt;return $('#context-message').focus()}if(el.dataset.action)return await handleAction(el.dataset.action);if(el.dataset.openProject)return openWorkspace(el.dataset.openProject);if(el.dataset.openContext)return openSharedRoom(el.dataset.openContext);if(el.dataset.openRun){appState.selectedRunId=el.dataset.openRun;appState.route='runs';return render()}if(el.dataset.openProjectRun){appState.selectedRunId=el.dataset.openProjectRun;return renderWorkspace()}if(el.dataset.retryRun){const sourceRun=appState.data.runs.find(r=>r.id===el.dataset.retryRun),sourceAgent=sourceRun?.agents?.find(a=>a.id===el.dataset.retryAgent);el.disabled=true;el.textContent='Starting again…';toast(`Retrying ${sourceAgent?.role||'failed agent'} with ${providerName(sourceAgent?.provider||'system')}.`);window.noor.orchestrator.retryAgent(el.dataset.retryRun,el.dataset.retryAgent).then(async result=>{if(!result.ok)toast(result.error,'error');else{appState.selectedRunId=result.data.id;toast(`${sourceAgent?.role||'Agent'} finished. Review the new edits.`)}await refreshState()}).catch(err=>{console.error(err);toast(err.message,'error');refreshState()});return}if(el.dataset.openFolder)return call(window.noor.projects.openFolder(el.dataset.openFolder));if(el.dataset.removeProject){const p=projectById(el.dataset.removeProject);return confirmModal('Remove project?',`${p?.name||'This project'} will leave Noor navigation. Its folder remains untouched.`,'Remove project',{type:'remove-project',id:el.dataset.removeProject})}if(el.dataset.backup){const r=await call(window.noor.tools.backup(el.dataset.backup));return toast(`Backup created with ${r.files} files.`)}if(el.dataset.preview){const r=await call(window.noor.tools.previewStart(el.dataset.preview));return toast(r.message)}if(el.dataset.cancelRun){await call(window.noor.orchestrator.cancel(el.dataset.cancelRun));return toast('Cancellation requested.')}if(el.dataset.reviewRun){if(el.dataset.reviewDecision==='reject')return confirmModal('Reject all agent edits?','The project will be restored to its exact state before this run. Files created by the agents will be removed.','Reject Edits',{type:'reject-edits',id:el.dataset.reviewRun});await call(window.noor.orchestrator.reviewEdits(el.dataset.reviewRun,'accept'));await refreshState();return toast('Agent edits accepted.')}if(el.dataset.handoff){const p=projectById(el.dataset.handoff),r=await call(window.noor.tools.handoff({projectId:p.id,goal:p.goal}));return toast(`Handoff created at ${r.file}`)}if(el.dataset.file){const d=await call(window.noor.projects.readFile(appState.currentProjectId,el.dataset.file));appState.currentFile=d.path;appState.fileContent=d.content;return renderWorkspace()}if(el.dataset.startRun){const plan=JSON.parse($('#modal-root').dataset.plan||'{}'),goal=$('#run-goal').value.trim();if(!goal)return errorFor('run-goal','Describe the outcome.');const assignments={};$$('[data-role-provider]').forEach(s=>assignments[s.dataset.roleProvider]=parseProviderChoice(s.value));const participants=[...new Set(Object.values(assignments).map(x=>x.provider))],contextId=appState.sharedContext?.projectId===appState.currentProjectId?appState.sharedContext.id:null;closeModal();toast(`${plan.parallel?'Parallel':'Sequential'} agent run started with ${participants.map(providerName).join(', ')}.`);window.noor.orchestrator.run({projectId:appState.currentProjectId,goal,participants,assignments,contextId,plan}).then(async r=>{if(!r.ok)toast(r.error,'error');else toast('Agent run finished. Review the file edits.');await refreshState()}).catch(err=>{console.error(err);toast(err.message,'error')})}}catch(err){console.error(err)}});
document.addEventListener('change',async e=>{const order=e.target.closest('[data-role-order]');if(order){const controls=$$('[data-role-order]',$('#modal-root')),previous=Number(order.dataset.previousOrder),selected=Number(order.value),occupied=controls.find(control=>control!==order&&Number(control.value)===selected);if(occupied){occupied.value=String(previous);occupied.dataset.previousOrder=String(previous)}order.dataset.previousOrder=String(selected);return}const s=e.target.closest('[data-provider-model]');if(s)try{await call(window.noor.providers.setModel(s.dataset.providerModel,s.value));await refreshState();toast('Default model updated.')}catch(err){console.error(err)}});
document.addEventListener('input',e=>{if(e.target.id&&e.target.hasAttribute('aria-invalid'))clearError(e.target.id)});
window.noor.events.onAgentProgress(p=>{const key=`${p.runId}:${p.agentId}`;appState.agentProgress[key]=p;const node=$$('[data-agent-progress]').find(item=>item.dataset.agentProgress===key);if(node)updateAgentProgressNode(node,p);else if(['workspace','runs'].includes(appState.route))render()});
window.noor.events.onStateChanged(s=>{appState.data=s;render()});window.noor.events.onRunUpdated(r=>{const i=appState.data.runs.findIndex(x=>x.id===r.id);if(i>=0)appState.data.runs[i]=r;else appState.data.runs.unshift(r);if(['workspace','runs','home'].includes(appState.route))render()});window.noor.events.onActivity(e=>{appState.events.unshift(e);if(appState.route==='activity'||appState.projectView==='history')render()});window.noor.events.onProviderProgress(p=>{const t=$('#progress-text'),f=$('#progress-fill');if(t){t.textContent+=`\n${p.status||''}`;t.scrollTop=t.scrollHeight}if(f&&Number.isFinite(p.percent)){f.parentElement.classList.remove('indeterminate');f.style.width=`${Math.max(0,Math.min(100,p.percent))}%`}});window.noor.events.onTerminal(({projectId,text})=>{appState.terminal[projectId]=(appState.terminal[projectId]||'')+text;if(appState.terminal[projectId].length>60000)appState.terminal[projectId]=appState.terminal[projectId].slice(-60000);const t=$('#terminal-output');if(t&&appState.currentProjectId===projectId){t.textContent=appState.terminal[projectId];t.scrollTop=t.scrollHeight}});window.noor.events.onContextMessage(({contextId,message})=>{if(!appState.sharedContext||appState.sharedContext.id!==contextId)return;if(!appState.sharedContext.messages.some(x=>x.id===message.id))appState.sharedContext.messages.push(message);appState.sharedContext.messageCount=appState.sharedContext.messages.length;if(appState.route==='collaboration')renderCollaboration()});window.noor.events.onContextProgress(p=>{if(appState.sharedContext&&p.contextId===appState.sharedContext.id){appState.contextStatus=p.status||`${providerName(p.provider)} is working…`;if(appState.route==='collaboration')renderCollaboration()}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)&&e.target?.id==='context-message'&&!appState.contextBusy){e.preventDefault();$('[data-action="send-context"]')?.click();return}const m=$('#modal-root .modal');if(!m)return;if(e.key==='Escape'){e.preventDefault();return closeModal()}if(e.key==='Tab'){const f=$$('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled])',m);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0]?.focus()}}});

document.addEventListener('click',async event=>{
  const deleteButton=event.target.closest('[data-delete-run]');
  if(deleteButton){
    const run=appState.data.runs.find(item=>item.id===deleteButton.dataset.deleteRun);
    return confirmModal('Delete this agent run?',`The run “${run?.goal||'Selected run'}” and its saved report will be removed from Noor. Project files and Shared Room messages are not affected.`,'Delete run',{type:'delete-run',id:deleteButton.dataset.deleteRun});
  }
  if(event.target.closest('[data-reset-app]')){
    appState.previousFocus=document.activeElement;
    return modal('Delete all application data','This action cannot be undone inside Noor AI Studio.',`<div class="reset-confirm">${notice('error','Application data will be erased','Projects will be unregistered and all runs, activity, settings, transcripts, and saved credentials will be deleted. Project folders and provider installations remain untouched.')}<div class="field"><label for="reset-confirmation">Type DELETE to confirm</label><input class="input" id="reset-confirmation" autocomplete="off" autofocus></div></div>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-danger" data-confirm-reset disabled>Delete all data</button>`);
  }
  if(event.target.closest('[data-action="confirm-pending"]')&&appState.pendingConfirmation?.type==='reject-edits'){
    const id=appState.pendingConfirmation.id;closeModal();await call(window.noor.orchestrator.reviewEdits(id,'reject'));await refreshState();return toast('Agent edits rejected. The project snapshot was restored.');
  }
  if(event.target.closest('[data-action="confirm-pending"]')&&appState.pendingConfirmation?.type==='delete-run'){
    const id=appState.pendingConfirmation.id;closeModal();appState.selectedRunId=null;appState.data=await call(window.noor.orchestrator.deleteRun(id));render();return toast('Agent run deleted.');
  }
  if(event.target.closest('[data-confirm-reset]')){
    const button=event.target.closest('[data-confirm-reset]');if(button.disabled)return;
    button.disabled=true;button.textContent='Deleting application data…';
    const state=await call(window.noor.app.resetData());closeModal();Object.assign(appState,{data:state,route:'home',currentProjectId:null,projectView:'overview',selectedRunId:null,currentFile:null,fileContent:'',files:[],events:[],terminal:{},sharedContext:null,sharedContextProjectId:null,contextBusy:false,contextStatus:'',contextParticipants:null,contextRounds:null});render();return toast('All Noor application data was deleted.');
  }
});

document.addEventListener('input',event=>{if(event.target.id==='reset-confirmation'){const button=$('[data-confirm-reset]');if(button)button.disabled=event.target.value.trim()!=='DELETE'}});

function openRouterKeyModal(){modal('Connect Ox Alpha','Noor validates the OpenRouter key and Ox Alpha availability, then encrypts the key with your operating system.',`${notice('warning','Anonymous preview and data retention','Ox Alpha is an anonymous preview model. Its provider retains prompts and completions.')}<div class="field"><label for="provider-key">OpenRouter API key</label><input class="input" id="provider-key" type="password" autocomplete="off" autofocus aria-describedby="provider-key-error"><span class="field-help">Create the key on OpenRouter. It is never written to normal state, logs, projects, diagnostics, or backups.</span><p class="form-error" id="provider-key-error" hidden></p></div>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="submit-openrouter-key">Connect</button>`)}
function enhanceOpenRouterUI(){
  const provider=appState.data?.providers?.openrouter;
  if(!provider)return;
  if(appState.route==='home'){
    const providerMetric=[...$$('.metrics > div')].find(node=>node.querySelector('span')?.textContent==='Providers ready');
    const total=providerMetric?.querySelector('em');if(total)total.textContent=`/${automaticProviderIds.length}`;
  }
  if(appState.route==='providers'){
    const summary=$('.provider-summary');
    const heading=summary?.querySelector('h2');if(heading)heading.textContent=`${connectedCount()} of ${automaticProviderIds.length} automatic providers ready`;
    if(summary&&!summary.querySelector('[data-openrouter-summary]'))summary.insertAdjacentHTML('beforeend',`<span data-openrouter-summary>${badge(provider.connected?'ready':'offline',providerName('openrouter'))}<small>${esc(provider.model||'No model selected')}</small></span>`);
    const grid=$('.provider-grid');
    if(grid&&![...grid.querySelectorAll('h2')].some(node=>node.textContent==='Ox Alpha')){
      const model=provider.models?.[0]||{};
      const capabilityDetails=`<div class="ox-capabilities" aria-label="Ox Alpha capabilities"><span><b>${esc(model.priceLabel||'Free')}</b> price</span><span><b>${count(model.contextWindow||1048576)}</b> context tokens</span><span><b>${count(model.outputTokenLimit||131072)}</b> max output tokens</span><span><b>Text, image, video</b> input</span><span><b>Text</b> output</span><span><b>Tools + JSON object</b> supported</span></div>${notice('warning','Anonymous preview and data retention',model.privacyNotice||'Ox Alpha is an anonymous preview model. Its provider retains prompts and completions.')}<p class="structured-output-note">JSON-object output is supported through <code>response_format</code>; strict JSON Schema enforcement is not guaranteed.</p>`;
      const cardHtml=providerCard('openrouter','Ox Alpha','Cloud · automatic · Free','OpenRouter model stealth/ox-alpha for reasoning, coding, and agentic work. It supports high-effort reasoning, long context, streaming, tools, images, video, and JSON-object output.',provider,`${provider.connected?'<button class="button button-danger" data-action="openrouter-disconnect">Disconnect</button>':'<button class="button button-primary" data-action="openrouter-connect">Connect OpenRouter</button>'}<button class="button button-quiet" data-action="openrouter-docs">Open model page</button>`,capabilityDetails);
      const manual=[...grid.children].find(card=>card.querySelector('h2')?.textContent==='Antigravity');
      if(manual)manual.insertAdjacentHTML('beforebegin',cardHtml);else grid.insertAdjacentHTML('beforeend',cardHtml);
    }
  }
  if(appState.route==='collaboration'&&!appState.sharedContextProjectId){
    const intro=$('.collaboration-intro');
    const copy=intro?.querySelector(':scope > div > p');if(copy)copy.textContent='Codex, Gemini, Ollama, and Ox Alpha can read the same project conversation and contribute in sequence. Each can see earlier contributions before responding.';
    const aside=intro?.querySelector('aside');
    if(aside&&!aside.querySelector('[data-openrouter-participant]')){
      const button=aside.querySelector('button');
      const row=`<div class="participant-summary-row" data-openrouter-participant><span class="provider-logo openrouter">${providerInitial('openrouter')}</span><span><strong>${providerName('openrouter')}</strong><small>${esc(provider.model||'No model selected')}</small></span>${badge(provider.connected?'ready':'offline',provider.connected?'Ready':'Not connected')}</div>`;
      if(button)button.insertAdjacentHTML('beforebegin',row);else aside.insertAdjacentHTML('beforeend',row);
    }
  }
  if(appState.route==='collaboration'&&appState.sharedContextProjectId){
    const list=$('.participant-list');
    if(list&&!list.querySelector('[data-context-provider="openrouter"]')){
      const ready=Boolean(provider.connected),preferred=appState.contextParticipants||appState.data.settings.defaultParticipants||options(),working=appState.contextBusy&&appState.contextStatus.toLowerCase().includes('ox alpha');
      const row=`<label class="participant ${ready?'':'offline'} ${working?'working':''}"><input type="checkbox" data-context-provider="openrouter" ${ready&&preferred.includes('openrouter')?'checked':''} ${ready?'':'disabled'}><span class="provider-logo openrouter">${providerInitial('openrouter')}</span><span><strong>${providerName('openrouter')}</strong><small>${ready?esc(provider.model||'Provider default'):'Not connected'}</small></span>${badge(working?'working':ready?'ready':'offline',working?'Working':ready?'Ready':'Offline')}</label>`;
      list.insertAdjacentHTML('beforeend',row);
    }
    const sidebar=$('.room-sidebar');if(sidebar&&!sidebar.querySelector('[data-ox-preview-notice]'))sidebar.insertAdjacentHTML('beforeend',`<div data-ox-preview-notice>${notice('warning','Ox Alpha preview privacy','Its provider retains prompts and completions. Select it only when this is appropriate for the project.')}</div>`);
  }
  if(appState.route==='settings'){
    const select=$('#default-provider');
    if(select&&!select.querySelector('option[value="openrouter"]')){const option=document.createElement('option');option.value='openrouter';option.textContent='Ox Alpha';option.selected=appState.data.settings.defaultProvider==='openrouter';select.append(option)}
  }
}
const renderWithoutOpenRouterEnhancement=render;
render=function(){renderWithoutOpenRouterEnhancement();enhanceOpenRouterUI()};
document.addEventListener('click',async event=>{
  const action=event.target.closest('[data-action]')?.dataset.action;
  if(!['openrouter-connect','submit-openrouter-key','openrouter-disconnect','openrouter-docs'].includes(action))return;
  event.preventDefault();event.stopImmediatePropagation();
  try{
    if(action==='openrouter-connect')return openRouterKeyModal();
    if(action==='openrouter-docs')return call(window.noor.providers.openUrl('openrouter'));
    if(action==='openrouter-disconnect'){await call(window.noor.providers.openRouterDisconnect());await refreshState();return toast('Ox Alpha disconnected.');}
    const key=$('#provider-key')?.value.trim();if(!key)return errorFor('provider-key','Enter an OpenRouter API key.');
    progressModal('Connecting Ox Alpha','Validating the OpenRouter key and model availability…');
    try{await call(window.noor.providers.openRouterConnect(key));toast('Ox Alpha connected with high reasoning effort.');}finally{closeModal();await refreshState();}
  }catch(error){console.error(error)}
},true);
function tokenInKeyModal(){modal('Connect TokenIn','Noor checks your key and discovers which requested free models are currently available, then encrypts the key with your operating system.',`<div class="field"><label for="tokenin-provider-key">TokenIn API key</label><input class="input" id="tokenin-provider-key" type="password" autocomplete="off" autofocus aria-describedby="tokenin-provider-key-error"><span class="field-help">Create the key on the TokenIn model dashboard. It stays in the protected main process and is excluded from normal state, logs, projects, diagnostics, and backups.</span><p class="form-error" id="tokenin-provider-key-error" hidden></p></div>`,`<button class="button button-secondary" data-action="close-modal">Cancel</button><button class="button button-primary" data-action="submit-tokenin-key">Connect</button>`)}
